import sys
from datetime import date, timedelta


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def main():
    holidays = set()
    allowance = {}
    used = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "holiday":
            holidays.add(parse(parts[1]))
        elif parts[0] == "allowance":
            allowance[parts[1]] = int(parts[2])
        elif parts[0] == "leave":
            name = parts[1]
            from_date_str = parts[2]
            to_date_str = parts[3]
            from_date = parse(from_date_str)
            to_date = parse(to_date_str)
            if from_date > to_date:
                continue
            count = 0
            current_date = from_date
            while current_date <= to_date:
                if current_date.weekday() < 5 and current_date not in holidays:
                    count += 1
                current_date += timedelta(days=1)
            used[name] = used.get(name, 0) + count
    for name in sorted(used.keys()):
        u = used[name]
        a = allowance.get(name, 0)
        if u <= a:
            left = a - u
            print(f"{name} used {u} left {left}")
        else:
            o = u - a
            print(f"{name} used {u} over {o}")


if __name__ == "__main__":
    main()
